    if (story.getLastAnswer() == "Beach") {

        // function

        pause(2000) // allowing a window for user view

    } else if (story.getLastAnswer() == "Smiley Face") {

        // function
        
        pause(2000) // allowing a window for user view

    } else {

        // function

        pause(2000)

    }

